function nthDia_(dia) {
  let s = norm_(dia).replace(/[º°ª]/g, '');
  s = s.replace(/^primeir\w*/, '1').replace(/^segund\w*(?=\s)/, '2').replace(/^terceir\w*/, '3').replace(/^quart\w*(?=\s)/, '4').replace(/^quint\w*(?=\s)/, '5').replace(/^ultim\w*/, 'u');
